import React, { useState } from "react";
import "../css/SignIn.css";
import googleIcon from "../assets/google-brands-solid.svg";
import twitterIcon from "../assets/x-twitter-brands-solid.svg";
import { useSignIn } from "@clerk/clerk-react";
import { Link, useNavigate } from "react-router-dom";

const SignIn = () => {
  const { signIn,  isLoaded, error: clerkError } = useSignIn();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  if (!isLoaded) return null; // Wait for Clerk to load

  const handleSignIn = async (e) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      // Attempt sign in with email and password
      await signIn.create({ identifier: email, password });

      // Redirect or do something after successful login, e.g. navigate dashboard
      navigate("/dashboard");
    } catch (err) {
      setError(err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="container">
      <h1 className="header">Login to your account</h1>
      <p className="subtext">
        Enter your email and password to log in or{" "}
        <Link to="/signup">create an account</Link>
      </p>

      <div className="button-group">
        <button
          type="button"
          className="button"
          onClick={() => {
            // TODO: Add Twitter OAuth logic here (Clerk supports OAuth)
            alert("Twitter login not implemented yet");
          }}
        >
          <img src={twitterIcon} alt="Twitter Icon" width={20} height={20} /> Twitter
        </button>
        <button
          type="button"
          className="button"
          onClick={() => {
            // TODO: Add Google OAuth logic here
            alert("Google login not implemented yet");
          }}
        >
          <img src={googleIcon} alt="Google Icon" width={20} height={20} /> Google
        </button>
      </div>

      <div className="divider">
        <span>OR</span>
      </div>

      <form onSubmit={handleSignIn}>
        <label htmlFor="email">Email</label>
        <input
          type="email"
          id="email"
          name="email"
          placeholder="m@example.com"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          autoComplete="username"
        />

        <label htmlFor="password">Password</label>
        <input
          type="password"
          id="password"
          name="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          minLength={8}
          autoComplete="current-password"
        />

        <button type="submit" className="submit" disabled={isLoading}>
          {isLoading ? "Logging in..." : "Log In"}
        </button>

        {(error || clerkError) && (
          <p className="error">{(error || clerkError).message || "Failed to sign in"}</p>
        )}
      </form>
    </div>
  );
};

export default SignIn;
